import json
from pathlib import Path
p=Path('map-preview/data/water.json');d=json.loads(p.read_text());d['water']=[z for z in d['water'] if z['id'].startswith('lake')]
def poly(n,coords,kind='water',**kw):
 if coords[0]!=coords[-1]:coords.append(coords[0])
 xs,ys=zip(*coords);return dict(id=n,name=n,kind=kind,bbox=[min(xs),min(ys),max(xs),max(ys)],geometry={'type':'Polygon','coordinates':[coords]},xy=[sum(xs[:-1])/(len(xs)-1),sum(ys[:-1])/(len(ys)-1)],**kw)
def box(n,x1,y1,x2,y2,kind='water',**kw):return poly(n,[[x1,y1],[x2,y1],[x2,y2],[x1,y2]],kind,**kw)
for n,coords in [
 ('不忍池',[[139.7690,35.7085],[139.7716,35.7100],[139.7712,35.7138],[139.7676,35.7141],[139.7671,35.7110]]),
 ('井の頭池',[[139.5745,35.6988],[139.5786,35.6979],[139.5801,35.6991],[139.5793,35.7001],[139.5762,35.6997]]),
 ('石神井池',[[139.6015,35.7386],[139.6070,35.7399],[139.6077,35.7392],[139.6026,35.7378]]),
 ('皇居・桜田濠',[[139.7474,35.6810],[139.7492,35.6775],[139.7537,35.6783],[139.7547,35.6793],[139.7501,35.6787],[139.7483,35.6810]]),
 ('皇居・千鳥ヶ淵',[[139.7468,35.6870],[139.7477,35.6920],[139.7511,35.6918],[139.7508,35.6912],[139.7485,35.6912],[139.7476,35.6870]]),
 ('東京湾中央部',[[139.788,35.566],[139.812,35.619],[139.854,35.628],[139.917,35.628],[139.982,35.594],[140.033,35.555],[140.023,35.484],[139.921,35.369],[139.803,35.323],[139.766,35.418],[139.797,35.505]])]:d['water'].append(poly(n,coords,source='手作業の概略水域。現況境界の保証なし'))
for n,xy,width in [
 ('多摩川下流',[[139.475,35.641],[139.522,35.627],[139.570,35.605],[139.620,35.586],[139.659,35.574],[139.689,35.550],[139.733,35.532],[139.776,35.522]],130),
 ('荒川下流',[[139.663,35.809],[139.708,35.792],[139.752,35.779],[139.779,35.767],[139.815,35.751],[139.841,35.727],[139.852,35.695],[139.852,35.666],[139.868,35.645]],160),
 ('江戸川下流',[[139.897,35.915],[139.891,35.868],[139.886,35.824],[139.902,35.791],[139.905,35.756],[139.907,35.728],[139.922,35.703],[139.939,35.677]],100),
 ('隅田川下流',[[139.784,35.730],[139.800,35.711],[139.802,35.688],[139.788,35.673],[139.783,35.654]],55),
 ('鶴見川下流',[[139.615,35.517],[139.641,35.523],[139.663,35.519],[139.683,35.507],[139.688,35.486]],45),
 ('利根川・千葉県境',[[139.77,36.096],[139.864,36.014],[139.939,35.915],[140.060,35.868],[140.15,35.867],[140.30,35.90],[140.44,35.89],[140.58,35.88],[140.70,35.86],[140.82,35.79]],150)]:
 xs,ys=zip(*xy);d['water'].append(dict(id=n,name=n,kind='water',bbox=[min(xs)-.003,min(ys)-.003,max(xs)+.003,max(ys)+.003],line=xy,width=width,source='主要河川中心線と水面幅の手作業近似。全流路・河川敷・橋を完全再現しない'))
p.write_text(json.dumps(d,ensure_ascii=False,separators=(',',':'))+'\n')
land=[]
land+=[poly('羽田空港・陸域',[[139.751,35.559],[139.769,35.577],[139.795,35.563],[139.805,35.544],[139.782,35.529],[139.760,35.539]],'airfield')]
land+=[box('羽田空港第1・第2ターミナル',139.780,35.546,139.790,35.558,'terminal'),box('羽田空港第3ターミナル',139.764,35.542,139.773,35.550,'terminal')]
