for n,b,k in [('大井ふ頭・物流地区',[139.747,35.589,139.770,35.612],'industrial'),('横浜・大黒ふ頭',[139.668,35.456,139.688,35.477],'industrial'),('川崎・東扇島',[139.743,35.483,139.780,35.503],'industrial'),('川崎・浮島',[139.781,35.515,139.804,35.530],'industrial'),('千葉・蘇我臨海工業地区',[140.097,35.560,140.116,35.588],'industrial'),('根岸臨海工業地区',[139.632,35.400,139.659,35.419],'industrial'),('東京貨物ターミナル',[139.740,35.591,139.747,35.605],'industrial'),('横田飛行場',[139.333,35.735,139.361,35.766],'airfield'),('入間飛行場',[139.398,35.836,139.421,35.854],'airfield'),('多磨霊園',[139.508,35.676,139.525,35.691],'cemetery'),('八柱霊園',[139.938,35.783,139.958,35.796],'cemetery'),('狭山丘陵の緑地',[139.391,35.768,139.439,35.786],'wildland')]:land.append(box(n,*b,kind=k))
# More specific terminal zones take priority over the airfield that contains them.
land.sort(key=lambda z:0 if z['kind']=='terminal' else 1)
Path('map-preview/data/land-zones.json').write_text(json.dumps({'notes':'主要な非住宅地の概略区域。実敷地境界・実人員ではない。空港の軍民別配置を再現しない。','zones':land},ensure_ascii=False,indent=2)+'\n');print(len(d['water']),len(land))

